with filtered_web_events as (select * from web_events where event_time < '2024-11-01' and to_date(event_time) < '2025-06-01'), WebEventsStats as (select case when duration_sec >= 504 then 'high' when duration_sec >= 236 then 'mid' else 'low' end as duration_sec_bucket, event_type, min(duration_sec) as min_duration_sec from filtered_web_events group by case when duration_sec >= 504 then 'high' when duration_sec >= 236 then 'mid' else 'low' end, event_type) select duration_sec_bucket, event_type from WebEventsStats order by event_type, duration_sec_bucket limit 10;
